import { test, expect } from '@playwright/test';

test.describe('Reorder List Items by Drag and Drop', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/list-items');
  });

  test('should reorder list items using drag and drop', async ({ page }) => {
    // Verify initial list order
    const listItems = page.locator('[data-testid="list-item"]');
    const initialOrder = await listItems.count();
    expect(initialOrder).toBeGreaterThan(0);

    // Verify list items are displayed
    const listContainer = page.getByTestId('list-container');
    await expect(listContainer).toBeVisible();

    // Verify list items have correct initial order
    const firstItem = page.getByText('Item 1');
    const secondItem = page.getByText('Item 2');
    const thirdItem = page.getByText('Item 3');
    await expect(firstItem).toBeVisible();
    await expect(secondItem).toBeVisible();
    await expect(thirdItem).toBeVisible();

    // Verify drag handles are visible
    const dragHandles = page.locator('[data-testid="drag-handle"]');
    await expect(dragHandles).toBeVisible();

    // Verify list items have correct initial data attributes
    const firstItemData = await firstItem.evaluate((el) => el.dataset.id);
    const secondItemData = await secondItem.evaluate((el) => el.dataset.id);
    const thirdItemData = await thirdItem.evaluate((el) => el.dataset.id);
    expect(firstItemData).toBe('item-1');
    expect(secondItemData).toBe('item-2');
    expect(thirdItemData).toBe('item-3');

    // Verify initial sort order is correct
    const firstItemOrder = await firstItem.evaluate((el) => el.dataset.order);
    const secondItemOrder = await secondItem.evaluate((el) => el.dataset.order);
    const thirdItemOrder = await thirdItem.evaluate((el) => el.dataset.order);
    expect(firstItemOrder).toBe('1');
    expect(secondItemOrder).toBe('2');
    expect(thirdItemOrder).toBe('3');

    // Drag second item to first position
    const secondItem = page.getByText('Item 2');
    const firstItem = page.getByText('Item 1');
    await secondItem.click();
    await firstItem.click();

    // Verify list items are reordered
    const firstItemOrderAfterDrag = await firstItem.evaluate((el) => el.dataset.order);
    const secondItemOrderAfterDrag = await secondItem.evaluate((el) => el.dataset.order);
    const thirdItemOrderAfterDrag = await thirdItem.evaluate((el) => el.dataset.order);
    expect(firstItemOrderAfterDrag).toBe('1');
    expect(secondItemOrderAfterDrag).toBe('1');
    expect(thirdItemOrderAfterDrag).toBe('2');

    // Verify list items are displayed in new order
    const firstItemAfterDrag = page.getByText('Item 2');
    const secondItemAfterDrag = page.getByText('Item 1');
    await expect(firstItemAfterDrag).toBeVisible();
    await expect(secondItemAfterDrag).toBeVisible();

    // Verify list container reflects new order
    const listContainerAfterDrag = page.getByTestId('list-container');
    await expect(listContainerAfterDrag).toContainText('Item 2');
    await expect(listContainerAfterDrag).toContainText('Item 1');

    // Verify drag handles are still visible
    const dragHandlesAfterDrag = page.locator('[data-testid="drag-handle"]');
    await expect(dragHandlesAfterDrag).toBeVisible();

    // Verify list items have updated data attributes
    const firstItemDataAfterDrag = await firstItemAfterDrag.evaluate((el) => el.dataset.id);
    const secondItemDataAfterDrag = await secondItemAfterDrag.evaluate((el) => el.dataset.id);
    expect(firstItemDataAfterDrag).toBe('item-2');
    expect(secondItemDataAfterDrag).toBe('item-1');
  });

  test('should handle empty list and prevent reordering', async ({ page }) => {
    // Verify list is empty
    const listContainer = page.getByTestId('list-container');
    await expect(listContainer).toBeEmpty();

    // Verify no list items are visible
    const listItems = page.locator('[data-testid="list-item"]');
    await expect(listItems).not.toBeVisible();

    // Verify no drag handles are visible
    const dragHandles = page.locator('[data-testid="drag-handle"]');
    await expect(dragHandles).not.toBeVisible();

    // Verify reorder button is disabled
    const reorderButton = page.getByRole('button', { name: /reorder/i });
    await expect(reorderButton).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText(/no items to reorder/i);
    await expect(errorMessage).toBeVisible();

    // Verify empty list state is maintained
    const listContainerAfterEmpty = page.getByTestId('list-container');
    await expect(listContainerAfterEmpty).toBeEmpty();
  });
});
